import { Navigation } from '@/components/navigation'
import { Button } from '@/components/ui/button'
import { CheckCircle2, HomeIcon } from 'lucide-react'
import React from 'react'

const OrderConfirmation = () => {
  return (
    <div className='flex flex-col justify-center items-center mt-20'>
        <Navigation/>
        <div className='flex justify-center items-center border shadow-md flex-col p-20 rounded-md gap-3 px-32 bg-secondary/30 h-fit md:h-[600px] max-w-2xl md:max-w-4xl lg:max-w-5xl '>
            <CheckCircle2 className='h-24 w-24 text-green-500'/>
            <h2 className='font-medium text-3xl text-primary'>
                Order Successfully placed
            </h2>
            <h2>Thank you for the order</h2>
            <Button onClick={()=>{
                window.location.href="/"
            }}>
                <HomeIcon/> Return Home
            </Button>
        </div>
    </div>
  )
}

export default OrderConfirmation